"""Fixed HTML and Web-PPT shells. Called by compose_story; not generated by an Agent."""

from __future__ import annotations

import html
import json
from pathlib import Path
from typing import Any

SKILL_DIR = Path(__file__).resolve().parents[1]


def read_text(path: Path) -> str:
    if not path.exists():
        raise FileNotFoundError(f"Required runtime file is missing: {path}")
    return path.read_text(encoding="utf-8")


def read_json(path: Path) -> dict[str, Any]:
    return json.loads(read_text(path))


def script_json(payload: Any) -> str:
    return json.dumps(payload, ensure_ascii=False).replace("</", "<\\/")


def motion_level_for_presentation_mode(presentation_mode: str) -> str:
    mode = presentation_mode.strip().lower()
    if mode == "feature":
        return "guided"
    if mode == "editorial":
        return "restrained"
    raise ValueError(
        f"Unsupported presentation_mode '{presentation_mode}'. Expected 'editorial' or 'feature'."
    )


def render_page(
    *,
    story_head: str,
    spec_map: dict[str, Any],
    body_html: str,
    title: str,
    lang: str,
    motion_level: str,
) -> str:
    vseed_render_js = read_text(SKILL_DIR / "scripts/vseed-render.js")
    pretext_js = read_text(SKILL_DIR / "build-html/scripts/vendor/pretext.browser.js")
    text_layout_js = read_text(SKILL_DIR / "build-html/scripts/story-text-layout.js")
    story_motion_js = read_text(SKILL_DIR / "build-html/scripts/story-motion.js")

    return f"""<!DOCTYPE html>
<html lang="{html.escape(lang, quote=True)}">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>{html.escape(title)}</title>
  {story_head}
  <script src="https://unpkg.com/@visactor/vseed@0.6.5/dist/umd/index.js"></script>
  <script src="https://unpkg.com/@visactor/vchart@2.1.7/build/index.min.js"></script>
  <script src="https://unpkg.com/@visactor/vtable@1.26.8/dist/vtable.min.js"></script>
  <script src="https://unpkg.com/gsap@3.15.0/dist/gsap.min.js"></script>
  <script src="https://unpkg.com/gsap@3.15.0/dist/ScrollTrigger.min.js"></script>
</head>
<body data-motion-level="{html.escape(motion_level, quote=True)}">
  {body_html}
  <script>
    window.VSEED_SPEC_MAP = {script_json(spec_map)};
  </script>
  <script>
{vseed_render_js}
  </script>
  <script>
{pretext_js}
  </script>
  <script>
{text_layout_js}
  </script>
  <script>
{story_motion_js}
  </script>
  <script>
    initVSeedCharts();
    initStoryTextLayout();
    initStoryMotion();
  </script>
</body>
</html>
"""


def render_deck(
    *,
    story_head: str,
    deck_runtime_js: str,
    vseed_render_js: str,
    spec_map: dict[str, Any],
    slides_html: str,
    title: str,
    lang: str,
    deck_axis: str,
) -> str:
    return f"""<!DOCTYPE html>
<html lang="{html.escape(lang, quote=True)}">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>{html.escape(title)}</title>
  {story_head}
  <script src="https://unpkg.com/@visactor/vseed@0.6.5/dist/umd/index.js"></script>
  <script src="https://unpkg.com/@visactor/vchart@2.1.7/build/index.min.js"></script>
  <script src="https://unpkg.com/@visactor/vtable@1.26.8/dist/vtable.min.js"></script>
</head>
<body>
  <main class="deck-shell" data-deck-shell data-deck-axis="{html.escape(deck_axis, quote=True)}">
    <canvas class="deck-bg-canvas" data-deck-bg-dark aria-hidden="true"></canvas>
    <canvas class="deck-bg-canvas" data-deck-bg-light aria-hidden="true"></canvas>
    <div class="deck-track" data-deck-track>
{slides_html}
    </div>
    <div class="deck-progress" aria-hidden="true"><div class="deck-progress-bar" data-deck-progress></div></div>
    <nav class="deck-dots" data-deck-dots aria-label="Slide navigation"></nav>
  </main>
  <script>
    window.VSEED_SPEC_MAP = {script_json(spec_map)};
  </script>
  <script>
{vseed_render_js}
  </script>
  <script>
{deck_runtime_js}
  </script>
  <script>
    initVSeedCharts();
    initStoryDeck();
  </script>
</body>
</html>
"""
